     1→/**
     2→ * Distribution Sampling Library for Threshold Uncertainty
     3→ *
     4→ * Implements research-backed probability distributions for modeling
     5→ * uncertain thresholds in planetary boundaries and crisis triggers.
     6→ *
     7→ * ALL functions are deterministic given the same RNG seed.
     8→ *
     9→ * Research foundations:
    10→ * - Box-Muller transform: Knuth (1997) - The Art of Computer Programming Vol 2
    11→ * - Beta sampling: Cheng (1978) - Generating beta variates with nonintegral shape parameters
    12→ * - Log-normal: Johnson et al. (1994) - Continuous Univariate Distributions Vol 1
    13→ * - Triangular: Law & Kelton (2000) - Simulation Modeling and Analysis
    14→ */
    15→
    16→import type { RNGFunction } from '@/types/config';
    17→import { assertFinite, assertInRange } from '@/simulation/utils/assertions';
    18→
    19→/**
    20→ * Sample from Normal distribution N(μ, σ²)
    21→ *
    22→ * Uses Box-Muller transform to convert uniform random variables to normal.
    23→ *
    24→ * Algorithm:
    25→ * 1. Generate two independent uniform [0,1] variables U1, U2
    26→ * 2. Z0 = sqrt(-2 ln(U1)) * cos(2π U2)
    27→ * 3. Z0 ~ N(0, 1)
    28→ * 4. Return μ + σ * Z0
    29→ *
    30→ * @param mean - Mean (μ) of distribution
    31→ * @param stdDev - Standard deviation (σ) of distribution, must be > 0
    32→ * @param rng - Deterministic RNG function
    33→ * @returns Sample from N(μ, σ²)
    34→ *
    35→ * @throws Error if stdDev ≤ 0 or parameters are NaN/Infinity
    36→ *
    37→ * @example
    38→ * const rng = seedrandom('test-seed');
    39→ * const sample = sampleNormal(100, 15, rng); // IQ-like distribution
    40→ */
    41→export function sampleNormal(
    42→  mean: number,
    43→  stdDev: number,
    44→  rng: RNGFunction
    45→): number {
    46→  // Validate parameters
    47→  assertFinite(mean, {
    48→    location: 'sampleNormal',
    49→    valueName: 'mean',
    50→    additionalInfo: { stdDev }
    51→  });
    52→
    53→  assertFinite(stdDev, {
    54→    location: 'sampleNormal',
    55→    valueName: 'stdDev',
    56→    additionalInfo: { mean }
    57→  });
    58→
    59→  if (stdDev <= 0) {
    60→    throw new Error([
    61→      '❌ Invalid stdDev in sampleNormal',
    62→      `   stdDev = ${stdDev}`,
    63→      '   stdDev must be > 0',
    64→    ].join('\n'));
    65→  }
    66→
    67→  // Box-Muller transform
    68→  const u1 = rng();
    69→  const u2 = rng();
    70→
    71→  // Avoid log(0) - if u1 is exactly 0, use tiny epsilon
    72→  const u1Safe = u1 === 0 ? 1e-10 : u1;
    73→
    74→  const z0 = Math.sqrt(-2.0 * Math.log(u1Safe)) * Math.cos(2.0 * Math.PI * u2);
    75→
    76→  const result = mean + stdDev * z0;
    77→
    78→  return assertFinite(result, {
    79→    location: 'sampleNormal',
    80→    valueName: 'result',
    81→    additionalInfo: { mean, stdDev, z0 }
    82→  });
    83→}
    84→
    85→/**
    86→ * Sample from Beta distribution Beta(α, β)
    87→ *
    88→ * Beta distribution models probabilities and proportions on [0, 1].
    89→ * - α, β = 1: Uniform [0,1]
    90→ * - α = β > 1: Symmetric, bell-shaped
    91→ * - α < β: Left-skewed (mode near 0)
    92→ * - α > β: Right-skewed (mode near 1)
    93→ *
    94→ * Uses gamma ratio method: Beta(α, β) = Gamma(α) / (Gamma(α) + Gamma(β))
    95→ *
    96→ * @param alpha - Shape parameter α, must be > 0
    97→ * @param beta - Shape parameter β, must be > 0
    98→ * @param rng - Deterministic RNG function
    99→ * @returns Sample from Beta(α, β) in [0, 1]
   100→ *
   101→ * @throws Error if alpha ≤ 0, beta ≤ 0, or parameters are NaN/Infinity
   102→ *
   103→ * @example
   104→ * const rng = seedrandom('test-seed');
   105→ * const sample = sampleBeta(2, 5, rng); // Left-skewed, mode near 0.2
   106→ */
   107→export function sampleBeta(
   108→  alpha: number,
   109→  beta: number,
   110→  rng: RNGFunction
   111→): number {
   112→  // Validate parameters
   113→  assertFinite(alpha, {
   114→    location: 'sampleBeta',
   115→    valueName: 'alpha',
   116→    additionalInfo: { beta }
   117→  });
   118→
   119→  assertFinite(beta, {
   120→    location: 'sampleBeta',
   121→    valueName: 'beta',
   122→    additionalInfo: { alpha }
   123→  });
   124→
   125→  if (alpha <= 0) {
   126→    throw new Error([
   127→      '❌ Invalid alpha in sampleBeta',
   128→      `   alpha = ${alpha}`,
   129→      '   alpha must be > 0',
   130→    ].join('\n'));
   131→  }
   132→
   133→  if (beta <= 0) {
   134→    throw new Error([
   135→      '❌ Invalid beta in sampleBeta',
   136→      `   beta = ${beta}`,
   137→      '   beta must be > 0',
   138→    ].join('\n'));
   139→  }
   140→
   141→  // Sample two gamma variates and take ratio
   142→  const gammaAlpha = sampleGamma(alpha, 1, rng);
   143→  const gammaBeta = sampleGamma(beta, 1, rng);
   144→
   145→  const result = gammaAlpha / (gammaAlpha + gammaBeta);
   146→
   147→  return assertInRange(result, 0, 1, {
   148→    location: 'sampleBeta',
   149→    valueName: 'result',
   150→  });
   151→}
   152→
   153→/**
   154→ * Sample from Gamma distribution Gamma(k, θ)
   155→ *
   156→ * Internal helper for Beta distribution.
   157→ * Uses Marsaglia & Tsang (2000) method for k ≥ 1.
   158→ *
   159→ * @param shape - Shape parameter k (α in some notations), must be > 0
   160→ * @param scale - Scale parameter θ, must be > 0
   161→ * @param rng - Deterministic RNG function
   162→ * @returns Sample from Gamma(k, θ)
   163→ */
   164→function sampleGamma(
   165→  shape: number,
   166→  scale: number,
   167→  rng: RNGFunction
   168→): number {
   169→  // For shape < 1, use transformation Gamma(k) = Gamma(k+1) * U^(1/k)
   170→  if (shape < 1) {
   171→    const gammaShapePlus1 = sampleGamma(shape + 1, scale, rng);
   172→    const u = rng();
   173→    return gammaShapePlus1 * Math.pow(u, 1 / shape);
   174→  }
   175→
   176→  // Marsaglia & Tsang (2000) method for shape ≥ 1
   177→  const d = shape - 1 / 3;
   178→  const c = 1 / Math.sqrt(9 * d);
   179→
   180→  // Rejection sampling loop
   181→  let maxIterations = 1000;
   182→  while (maxIterations-- > 0) {
   183→    // Sample Z ~ N(0,1)
   184→    const z = sampleNormal(0, 1, rng);
   185→    const v = Math.pow(1 + c * z, 3);
   186→
   187→    if (v <= 0) continue;
   188→
   189→    const u = rng();
   190→    const z2 = z * z;
   191→
   192→    // Accept/reject conditions from Marsaglia & Tsang
   193→    if (u < 1 - 0.0331 * z2 * z2) {
   194→      return d * v * scale;
   195→    }
   196→
   197→    if (Math.log(u) < 0.5 * z2 + d * (1 - v + Math.log(v))) {
   198→      return d * v * scale;
   199→    }
   200→  }
   201→
   202→  // Fallback - should rarely happen with good RNG
   203→  throw new Error('sampleGamma: Failed to converge after 1000 iterations');
   204→}
   205→
   206→/**
   207→ * Sample from Log-Normal distribution LogNormal(μ, σ²)
   208→ *
   209→ * Log-normal models positive-only values where log(X) ~ N(μ, σ²).
   210→ * Common in modeling multiplicative processes (e.g., economic growth).
   211→ *
   212→ * If Y ~ N(μ, σ²), then X = exp(Y) ~ LogNormal(μ, σ²)
   213→ *
   214→ * Mean of X = exp(μ + σ²/2)
   215→ * Median of X = exp(μ)
   216→ *
   217→ * @param mu - Mean of underlying normal distribution (NOT mean of log-normal)
   218→ * @param sigma - Std dev of underlying normal distribution, must be > 0
   219→ * @param rng - Deterministic RNG function
   220→ * @returns Sample from LogNormal(μ, σ²), always > 0
   221→ *
   222→ * @throws Error if sigma ≤ 0 or parameters are NaN/Infinity
   223→ *
   224→ * @example
   225→ * const rng = seedrandom('test-seed');
   226→ * // Threshold with median = 1.5°C, high variance
   227→ * const threshold = sampleLogNormal(Math.log(1.5), 0.3, rng);
   228→ */
   229→export function sampleLogNormal(
   230→  mu: number,
   231→  sigma: number,
   232→  rng: RNGFunction
   233→): number {
   234→  // Validate parameters
   235→  assertFinite(mu, {
   236→    location: 'sampleLogNormal',
   237→    valueName: 'mu',
   238→    additionalInfo: { sigma }
   239→  });
   240→
   241→  assertFinite(sigma, {
   242→    location: 'sampleLogNormal',
   243→    valueName: 'sigma',
   244→    additionalInfo: { mu }
   245→  });
   246→
   247→  if (sigma <= 0) {
   248→    throw new Error([
   249→      '❌ Invalid sigma in sampleLogNormal',
   250→      `   sigma = ${sigma}`,
   251→      '   sigma must be > 0',
   252→    ].join('\n'));
   253→  }
   254→
   255→  // Sample from normal, then exponentiate
   256→  const normalSample = sampleNormal(mu, sigma, rng);
   257→  const result = Math.exp(normalSample);
   258→
   259→  return assertFinite(result, {
   260→    location: 'sampleLogNormal',
   261→    valueName: 'result',
   262→    additionalInfo: { mu, sigma, normalSample }
   263→  });
   264→}
   265→
   266→/**
   267→ * Sample from Triangular distribution Tri(min, mode, max)
   268→ *
   269→ * Triangular distribution models expert estimates with:
   270→ * - Minimum plausible value
   271→ * - Most likely value (mode)
   272→ * - Maximum plausible value
   273→ *
   274→ * Uses inverse CDF method:
   275→ * - F(x) = (x-a)²/((b-a)(c-a)) for x ∈ [a, c]
   276→ * - F(x) = 1 - (b-x)²/((b-a)(b-c)) for x ∈ [c, b]
   277→ *
   278→ * @param min - Minimum value, must be < mode
   279→ * @param mode - Most likely value (peak), must be in (min, max)
   280→ * @param max - Maximum value, must be > mode
   281→ * @param rng - Deterministic RNG function
   282→ * @returns Sample from Tri(min, mode, max) in [min, max]
   283→ *
   284→ * @throws Error if min ≥ mode, mode ≥ max, or parameters are NaN/Infinity
   285→ *
   286→ * @example
   287→ * const rng = seedrandom('test-seed');
   288→ * // Ocean pH threshold: most likely 7.8, range [7.6, 8.0]
   289→ * const threshold = sampleTriangular(7.6, 7.8, 8.0, rng);
   290→ */
   291→export function sampleTriangular(
   292→  min: number,
   293→  mode: number,
   294→  max: number,
   295→  rng: RNGFunction
   296→): number {
   297→  // Validate parameters
   298→  assertFinite(min, {
   299→    location: 'sampleTriangular',
   300→    valueName: 'min',
   301→    additionalInfo: { mode, max }
   302→  });
   303→
   304→  assertFinite(mode, {
   305→    location: 'sampleTriangular',
   306→    valueName: 'mode',
   307→    additionalInfo: { min, max }
   308→  });
   309→
   310→  assertFinite(max, {
   311→    location: 'sampleTriangular',
   312→    valueName: 'max',
   313→    additionalInfo: { min, mode }
   314→  });
   315→
   316→  if (min >= mode) {
   317→    throw new Error([
   318→      '❌ Invalid parameters in sampleTriangular',
   319→      `   min = ${min}, mode = ${mode}`,
   320→      '   min must be < mode',
   321→    ].join('\n'));
   322→  }
   323→
   324→  if (mode >= max) {
   325→    throw new Error([
   326→      '❌ Invalid parameters in sampleTriangular',
   327→      `   mode = ${mode}, max = ${max}`,
   328→      '   mode must be < max',
   329→    ].join('\n'));
   330→  }
   331→
   332→  // Inverse CDF method
   333→  const u = rng();
   334→  const range = max - min;
   335→  const modeCDF = (mode - min) / range; // CDF value at mode
   336→
   337→  let result: number;
   338→
   339→  if (u < modeCDF) {
   340→    // Left side of triangle: [min, mode]
   341→    result = min + Math.sqrt(u * range * (mode - min));
   342→  } else {
   343→    // Right side of triangle: [mode, max]
   344→    result = max - Math.sqrt((1 - u) * range * (max - mode));
   345→  }
   346→
   347→  return assertInRange(result, min, max, {
   348→    location: 'sampleTriangular',
   349→    valueName: 'result',
   350→  });
   351→}
   352→
   353→/**
   354→ * Helper: Convert distribution parameters to descriptive stats
   355→ *
   356→ * Useful for logging and debugging threshold configurations.
   357→ *
   358→ * @example
   359→ * const stats = getDistributionStats('normal', { mean: 1.5, stdDev: 0.3 });
   360→ * console.log(stats); // "Normal(μ=1.50, σ=0.30)"
   361→ */
   362→export function getDistributionStats(
   363→  type: 'normal' | 'beta' | 'lognormal' | 'triangular',
   364→  params: Record<string, number>
   365→): string {
   366→  switch (type) {
   367→    case 'normal':
   368→      return `Normal(μ=${params.mean?.toFixed(2)}, σ=${params.stdDev?.toFixed(2)})`;
   369→    case 'beta':
   370→      return `Beta(α=${params.alpha?.toFixed(2)}, β=${params.beta?.toFixed(2)})`;
   371→    case 'lognormal':
   372→      return `LogNormal(μ=${params.mu?.toFixed(2)}, σ=${params.sigma?.toFixed(2)})`;
   373→    case 'triangular':
   374→      return `Triangular(min=${params.min?.toFixed(2)}, mode=${params.mode?.toFixed(2)}, max=${params.max?.toFixed(2)})`;
   375→    default:
   376→      return 'Unknown distribution';
   377→  }
   378→}
   379→

