/**
 * Distribution Sampling Library for Threshold Uncertainty
 *
 * Implements research-backed probability distributions for modeling
 * uncertain thresholds in planetary boundaries and crisis triggers.
 *
 * ALL functions are deterministic given the same RNG seed.
 *
 * Research foundations:
 * - Box-Muller transform: Knuth (1997) - The Art of Computer Programming Vol 2
 * - Beta sampling: Cheng (1978) - Generating beta variates with nonintegral shape parameters
 * - Log-normal: Johnson et al. (1994) - Continuous Univariate Distributions Vol 1
 * - Triangular: Law & Kelton (2000) - Simulation Modeling and Analysis
 */

import type { RNGFunction } from '@/types/config';
import { assertFinite, assertInRange } from '@/simulation/utils/assertions';

/**
 * Sample from Normal distribution N(μ, σ²)
 *
 * Uses Box-Muller transform to convert uniform random variables to normal.
 *
 * Algorithm:
 * 1. Generate two independent uniform [0,1] variables U1, U2
 * 2. Z0 = sqrt(-2 ln(U1)) * cos(2π U2)
 * 3. Z0 ~ N(0, 1)
 * 4. Return μ + σ * Z0
 *
 * @param mean - Mean (μ) of distribution
 * @param stdDev - Standard deviation (σ) of distribution, must be > 0
 * @param rng - Deterministic RNG function
 * @returns Sample from N(μ, σ²)
 *
 * @throws Error if stdDev ≤ 0 or parameters are NaN/Infinity
 *
 * @example
 * const rng = seedrandom('test-seed');
 * const sample = sampleNormal(100, 15, rng); // IQ-like distribution
 */
export function sampleNormal(
  mean: number,
  stdDev: number,
  rng: RNGFunction
): number {
  // Validate parameters
  assertFinite(mean, {
    location: 'sampleNormal',
    valueName: 'mean',
    additionalInfo: { stdDev }
  });

  assertFinite(stdDev, {
    location: 'sampleNormal',
    valueName: 'stdDev',
    additionalInfo: { mean }
  });

  if (stdDev <= 0) {
    throw new Error([
      '❌ Invalid stdDev in sampleNormal',
      `   stdDev = ${stdDev}`,
      '   stdDev must be > 0',
    ].join('\n'));
  }

  // Box-Muller transform
  const u1 = rng();
  const u2 = rng();

  // Avoid log(0) - if u1 is exactly 0, use tiny epsilon
  const u1Safe = u1 === 0 ? 1e-10 : u1;

  const z0 = Math.sqrt(-2.0 * Math.log(u1Safe)) * Math.cos(2.0 * Math.PI * u2);

  const result = mean + stdDev * z0;

  return assertFinite(result, {
    location: 'sampleNormal',
    valueName: 'result',
    additionalInfo: { mean, stdDev, z0 }
  });
}

/**
 * Sample from Beta distribution Beta(α, β)
 *
 * Beta distribution models probabilities and proportions on [0, 1].
 * - α, β = 1: Uniform [0,1]
 * - α = β > 1: Symmetric, bell-shaped
 * - α < β: Left-skewed (mode near 0)
 * - α > β: Right-skewed (mode near 1)
 *
 * Uses gamma ratio method: Beta(α, β) = Gamma(α) / (Gamma(α) + Gamma(β))
 *
 * @param alpha - Shape parameter α, must be > 0
 * @param beta - Shape parameter β, must be > 0
 * @param rng - Deterministic RNG function
 * @returns Sample from Beta(α, β) in [0, 1]
 *
 * @throws Error if alpha ≤ 0, beta ≤ 0, or parameters are NaN/Infinity
 *
 * @example
 * const rng = seedrandom('test-seed');
 * const sample = sampleBeta(2, 5, rng); // Left-skewed, mode near 0.2
 */
export function sampleBeta(
  alpha: number,
  beta: number,
  rng: RNGFunction
): number {
  // Validate parameters
  assertFinite(alpha, {
    location: 'sampleBeta',
    valueName: 'alpha',
    additionalInfo: { beta }
  });

  assertFinite(beta, {
    location: 'sampleBeta',
    valueName: 'beta',
    additionalInfo: { alpha }
  });

  if (alpha <= 0) {
    throw new Error([
      '❌ Invalid alpha in sampleBeta',
      `   alpha = ${alpha}`,
      '   alpha must be > 0',
    ].join('\n'));
  }

  if (beta <= 0) {
    throw new Error([
      '❌ Invalid beta in sampleBeta',
      `   beta = ${beta}`,
      '   beta must be > 0',
    ].join('\n'));
  }

  // Sample two gamma variates and take ratio
  const gammaAlpha = sampleGamma(alpha, 1, rng);
  const gammaBeta = sampleGamma(beta, 1, rng);

  const result = gammaAlpha / (gammaAlpha + gammaBeta);

  return assertInRange(result, 0, 1, {
    location: 'sampleBeta',
    valueName: 'result',
  });
}

/**
 * Sample from Gamma distribution Gamma(k, θ)
 *
 * Internal helper for Beta distribution.
 * Uses Marsaglia & Tsang (2000) method for k ≥ 1.
 *
 * @param shape - Shape parameter k (α in some notations), must be > 0
 * @param scale - Scale parameter θ, must be > 0
 * @param rng - Deterministic RNG function
 * @returns Sample from Gamma(k, θ)
 */
function sampleGamma(
  shape: number,
  scale: number,
  rng: RNGFunction
): number {
  // For shape < 1, use transformation Gamma(k) = Gamma(k+1) * U^(1/k)
  if (shape < 1) {
    const gammaShapePlus1 = sampleGamma(shape + 1, scale, rng);
    const u = rng();
    return gammaShapePlus1 * Math.pow(u, 1 / shape);
  }

  // Marsaglia & Tsang (2000) method for shape ≥ 1
  const d = shape - 1 / 3;
  const c = 1 / Math.sqrt(9 * d);

  // Rejection sampling loop
  let maxIterations = 1000;
  while (maxIterations-- > 0) {
    // Sample Z ~ N(0,1)
    const z = sampleNormal(0, 1, rng);
    const v = Math.pow(1 + c * z, 3);

    if (v <= 0) continue;

    const u = rng();
    const z2 = z * z;

    // Accept/reject conditions from Marsaglia & Tsang
    if (u < 1 - 0.0331 * z2 * z2) {
      return d * v * scale;
    }

    if (Math.log(u) < 0.5 * z2 + d * (1 - v + Math.log(v))) {
      return d * v * scale;
    }
  }

  // Fallback - should rarely happen with good RNG
  throw new Error('sampleGamma: Failed to converge after 1000 iterations');
}

/**
 * Sample from Log-Normal distribution LogNormal(μ, σ²)
 *
 * Log-normal models positive-only values where log(X) ~ N(μ, σ²).
 * Common in modeling multiplicative processes (e.g., economic growth).
 *
 * If Y ~ N(μ, σ²), then X = exp(Y) ~ LogNormal(μ, σ²)
 *
 * Mean of X = exp(μ + σ²/2)
 * Median of X = exp(μ)
 *
 * @param mu - Mean of underlying normal distribution (NOT mean of log-normal)
 * @param sigma - Std dev of underlying normal distribution, must be > 0
 * @param rng - Deterministic RNG function
 * @returns Sample from LogNormal(μ, σ²), always > 0
 *
 * @throws Error if sigma ≤ 0 or parameters are NaN/Infinity
 *
 * @example
 * const rng = seedrandom('test-seed');
 * // Threshold with median = 1.5°C, high variance
 * const threshold = sampleLogNormal(Math.log(1.5), 0.3, rng);
 */
export function sampleLogNormal(
  mu: number,
  sigma: number,
  rng: RNGFunction
): number {
  // Validate parameters
  assertFinite(mu, {
    location: 'sampleLogNormal',
    valueName: 'mu',
    additionalInfo: { sigma }
  });

  assertFinite(sigma, {
    location: 'sampleLogNormal',
    valueName: 'sigma',
    additionalInfo: { mu }
  });

  if (sigma <= 0) {
    throw new Error([
      '❌ Invalid sigma in sampleLogNormal',
      `   sigma = ${sigma}`,
      '   sigma must be > 0',
    ].join('\n'));
  }

  // Sample from normal, then exponentiate
  const normalSample = sampleNormal(mu, sigma, rng);
  const result = Math.exp(normalSample);

  return assertFinite(result, {
    location: 'sampleLogNormal',
    valueName: 'result',
    additionalInfo: { mu, sigma, normalSample }
  });
}

/**
 * Sample from Triangular distribution Tri(min, mode, max)
 *
 * Triangular distribution models expert estimates with:
 * - Minimum plausible value
 * - Most likely value (mode)
 * - Maximum plausible value
 *
 * Uses inverse CDF method:
 * - F(x) = (x-a)²/((b-a)(c-a)) for x ∈ [a, c]
 * - F(x) = 1 - (b-x)²/((b-a)(b-c)) for x ∈ [c, b]
 *
 * @param min - Minimum value, must be < mode
 * @param mode - Most likely value (peak), must be in (min, max)
 * @param max - Maximum value, must be > mode
 * @param rng - Deterministic RNG function
 * @returns Sample from Tri(min, mode, max) in [min, max]
 *
 * @throws Error if min ≥ mode, mode ≥ max, or parameters are NaN/Infinity
 *
 * @example
 * const rng = seedrandom('test-seed');
 * // Ocean pH threshold: most likely 7.8, range [7.6, 8.0]
 * const threshold = sampleTriangular(7.6, 7.8, 8.0, rng);
 */
export function sampleTriangular(
  min: number,
  mode: number,
  max: number,
  rng: RNGFunction
): number {
  // Validate parameters
  assertFinite(min, {
    location: 'sampleTriangular',
    valueName: 'min',
    additionalInfo: { mode, max }
  });

  assertFinite(mode, {
    location: 'sampleTriangular',
    valueName: 'mode',
    additionalInfo: { min, max }
  });

  assertFinite(max, {
    location: 'sampleTriangular',
    valueName: 'max',
    additionalInfo: { min, mode }
  });

  if (min >= mode) {
    throw new Error([
      '❌ Invalid parameters in sampleTriangular',
      `   min = ${min}, mode = ${mode}`,
      '   min must be < mode',
    ].join('\n'));
  }

  if (mode >= max) {
    throw new Error([
      '❌ Invalid parameters in sampleTriangular',
      `   mode = ${mode}, max = ${max}`,
      '   mode must be < max',
    ].join('\n'));
  }

  // Inverse CDF method
  const u = rng();
  const range = max - min;
  const modeCDF = (mode - min) / range; // CDF value at mode

  let result: number;

  if (u < modeCDF) {
    // Left side of triangle: [min, mode]
    result = min + Math.sqrt(u * range * (mode - min));
  } else {
    // Right side of triangle: [mode, max]
    result = max - Math.sqrt((1 - u) * range * (max - mode));
  }

  return assertInRange(result, min, max, {
    location: 'sampleTriangular',
    valueName: 'result',
  });
}

/**
 * Helper: Convert distribution parameters to descriptive stats
 *
 * Useful for logging and debugging threshold configurations.
 *
 * @example
 * const stats = getDistributionStats('normal', { mean: 1.5, stdDev: 0.3 });
 * console.log(stats); // "Normal(μ=1.50, σ=0.30)"
 */
export function getDistributionStats(
  type: 'normal' | 'beta' | 'lognormal' | 'triangular',
  params: Record<string, number>
): string {
  switch (type) {
    case 'normal':
      return `Normal(μ=${params.mean?.toFixed(2)}, σ=${params.stdDev?.toFixed(2)})`;
    case 'beta':
      return `Beta(α=${params.alpha?.toFixed(2)}, β=${params.beta?.toFixed(2)})`;
    case 'lognormal':
      return `LogNormal(μ=${params.mu?.toFixed(2)}, σ=${params.sigma?.toFixed(2)})`;
    case 'triangular':
      return `Triangular(min=${params.min?.toFixed(2)}, mode=${params.mode?.toFixed(2)}, max=${params.max?.toFixed(2)})`;
    default:
      return 'Unknown distribution';
  }
}

/**
 * Tier 1 Threshold Configurations - Phase 1B
 *
 * Defines research-backed uncertainty distributions for critical simulation thresholds.
 * Uses Phase 1A distribution sampling library for parameter variation.
 *
 * Research Foundation:
 * - Social Critical Mass: Centola et al. (2018, Science) - 25% committed minority
 * - Trust Recovery: Meta-analysis of trust repair interventions
 * - Climate Sensitivity: IPCC AR6 WG1 (2021) - ECS 3.0°C [2.0-5.0°C likely range]
 * - Government Legitimacy: Historical state collapse analysis
 * - Automation Job Loss: Acemoglu & Restrepo (2022) - labor market disruption
 */

import {
  sampleNormal,
  sampleBeta,
  sampleLogNormal,
  sampleTriangular
} from './distributions';

/**
 * Tier 1 Threshold Distribution Definitions
 *
 * These configurations define uncertainty distributions for critical thresholds.
 * Each threshold samples from a research-backed distribution during initialization.
 */

/**
 * 1. SOCIAL CRITICAL MASS
 *
 * Research: Centola et al. (2018, Science) "Experimental evidence for tipping points in social convention"
 * Finding: Committed minorities of ~25% can flip majority opinion
 * Uncertainty: ±2% based on experimental variance
 * Distribution: Normal(μ=0.25, σ=0.02)
 */
export const SOCIAL_CRITICAL_MASS_PARAMS = {
  mean: 0.25,
  stdDev: 0.02,
  bounds: [0.20, 0.30] as [number, number], // Clip to reasonable range
  citation: 'Centola et al. (2018, Science) - tipping points in social convention'
};

/**
 * 2. TRUST RECOVERY RATE (monthly)
 *
 * Research: Meta-analysis of trust repair studies (Gillespie & Dietz 2009, Lewicki & Brinsfield 2017)
 * Finding: Trust recovery is asymmetric - slower than loss
 * Typical recovery: 1-3% per month with intervention (mode ~1.5%)
 * Distribution: Beta(α=2, β=5) rescaled to [0.005, 0.03] (0.5-3% monthly recovery)
 *
 * Beta(2,5) shape: Right-skewed, most weight at lower values (slow recovery typical)
 */
export const TRUST_RECOVERY_RATE_PARAMS = {
  alpha: 2.0,
  beta: 5.0,
  bounds: [0.005, 0.03] as [number, number], // 0.5-3% monthly recovery
  citation: 'Gillespie & Dietz (2009), Lewicki & Brinsfield (2017) - trust repair meta-analysis'
};

/**
 * 3. CLIMATE SENSITIVITY (Equilibrium Climate Sensitivity, ECS)
 *
 * Research: IPCC AR6 WG1 (2021) Chapter 7 - Earth's Energy Budget
 * Finding: Best estimate 3.0°C, likely range 2.5-4.0°C, very likely 2.0-5.0°C
 * Distribution: Log-Normal(μ=3.0, σ=0.75) captures right-skewed uncertainty
 *
 * Log-normal justification: Physical constraints prevent negative ECS, small chance of high ECS
 * Note: This is ECS in °C, needs conversion to simulation degradation rate
 */
export const CLIMATE_SENSITIVITY_PARAMS = {
  mu: 3.0,
  sigma: 0.75,
  bounds: [2.0, 5.0] as [number, number], // IPCC very likely range
  citation: 'IPCC AR6 WG1 (2021) Ch 7 - Equilibrium Climate Sensitivity'
};

/**
 * 4. GOVERNMENT LEGITIMACY CRISIS THRESHOLD
 *
 * Research: Historical state collapse analysis (Weimar, USSR, various failed states)
 * Finding: Collapse typically occurs 25-40% legitimacy, mode ~30%
 * Distribution: Triangular(min=0.25, mode=0.30, max=0.40)
 *
 * Triangular justification: Expert elicitation with clear mode, bounded by historical cases
 * Below 25%: Nearly always collapse
 * 30%: Most common collapse point
 * Above 40%: Rare to collapse (other factors usually intervene)
 */
export const GOVERNMENT_LEGITIMACY_CRISIS_PARAMS = {
  min: 0.25,
  mode: 0.30,
  max: 0.40,
  citation: 'Historical state collapse analysis (Weimar, USSR, failed states)'
};

/**
 * 5. AUTOMATION JOB LOSS THRESHOLD
 *
 * Research: Acemoglu & Restrepo (2022) "Tasks, Automation, and the Rise in US Wage Inequality"
 * Finding: Automation displaces ~35% of routine tasks, ±5% based on policy/adaptation
 * Distribution: Normal(μ=0.35, σ=0.05)
 *
 * Note: This is the unemployment level at which automation-driven crises trigger
 * Societies with strong safety nets tolerate higher unemployment (40%)
 * Societies with weak safety nets crisis at lower levels (30%)
 */
export const AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS = {
  mean: 0.35,
  stdDev: 0.05,
  bounds: [0.25, 0.45] as [number, number], // Clip to plausible range
  citation: 'Acemoglu & Restrepo (2022) - automation and labor market disruption'
};

/**
 * Sample all Tier 1 thresholds for a simulation run
 *
 * @param rng - Random number generator function (for deterministic seeding)
 * @returns Sampled threshold values
 */
export interface Tier1Thresholds {
  socialCriticalMass: number;
  trustRecoveryRate: number;
  climateSensitivity: number;
  governmentLegitimacyCrisisThreshold: number;
  automationJobLossThreshold: number;
}

export function sampleTier1Thresholds(rng: () => number): Tier1Thresholds {
  // Sample raw values from distributions
  const socialCriticalMass = sampleNormal(
    SOCIAL_CRITICAL_MASS_PARAMS.mean,
    SOCIAL_CRITICAL_MASS_PARAMS.stdDev,
    rng
  );

  const trustRecoveryRateRaw = sampleBeta(
    TRUST_RECOVERY_RATE_PARAMS.alpha,
    TRUST_RECOVERY_RATE_PARAMS.beta,
    rng
  );

  const climateSensitivity = sampleLogNormal(
    CLIMATE_SENSITIVITY_PARAMS.mu,
    CLIMATE_SENSITIVITY_PARAMS.sigma,
    rng
  );

  const governmentLegitimacyCrisisThreshold = sampleTriangular(
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.min,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.mode,
    GOVERNMENT_LEGITIMACY_CRISIS_PARAMS.max,
    rng
  );

  const automationJobLossThreshold = sampleNormal(
    AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.mean,
    AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.stdDev,
    rng
  );

  // Apply bounds by clamping to valid ranges
  return {
    socialCriticalMass: Math.max(
      SOCIAL_CRITICAL_MASS_PARAMS.bounds[0],
      Math.min(SOCIAL_CRITICAL_MASS_PARAMS.bounds[1], socialCriticalMass)
    ),
    trustRecoveryRate: TRUST_RECOVERY_RATE_PARAMS.bounds[0] +
      (trustRecoveryRateRaw * (TRUST_RECOVERY_RATE_PARAMS.bounds[1] - TRUST_RECOVERY_RATE_PARAMS.bounds[0])),
    climateSensitivity: Math.max(
      CLIMATE_SENSITIVITY_PARAMS.bounds[0],
      Math.min(CLIMATE_SENSITIVITY_PARAMS.bounds[1], climateSensitivity)
    ),
    governmentLegitimacyCrisisThreshold: governmentLegitimacyCrisisThreshold, // Already bounded by triangular
    automationJobLossThreshold: Math.max(
      AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.bounds[0],
      Math.min(AUTOMATION_JOB_LOSS_THRESHOLD_PARAMS.bounds[1], automationJobLossThreshold)
    )
  };
}

/**
 * Convert climate sensitivity (°C per doubling CO2) to simulation degradation rate
 *
 * IPCC AR6: Current trajectory is ~SSP5-8.5 (high emissions)
 * - Emissions double CO2 every ~35-50 years at current pace
 * - ECS determines final warming, but rate depends on emissions path
 *
 * Simplified conversion for simulation:
 * - Base rate calibrated to IPCC SSP5-8.5 trajectory (0.00015 for ECS=3.0°C)
 * - Scale linearly with ECS (higher sensitivity = faster degradation)
 *
 * @param climateSensitivity - Sampled ECS value (°C)
 * @returns Monthly climate degradation rate
 */
export function convertClimateSensitivityToRate(climateSensitivity: number): number {
  const BASELINE_ECS = 3.0; // IPCC best estimate
  const BASELINE_RATE = 0.00015; // Calibrated to IPCC SSP5-8.5

  // Scale rate linearly with ECS
  // ECS=2.0°C → 67% of baseline rate
  // ECS=3.0°C → 100% of baseline rate
  // ECS=5.0°C → 167% of baseline rate
  return BASELINE_RATE * (climateSensitivity / BASELINE_ECS);
}

