    aiAgents.push(createAIAgent(`moderate_${i}`, `Moderate-${i}`, 0.05 + i * 0.01, alignment, (i + 8) * 1.3));
  }

  // Category 3: Misaligned from the start (15% - 3 agents)
  // Toxic creators, poor training, intentional harm
  for (let i = 0; i < 3; i++) {
